import * as Parchment from 'parchment';

// Core blots that must always be present
const CORE_BLOT_NAMES = [
  'block',
  'break',
  'cursor',
  'inline',
  'scroll',
  'text',
];

const CORE_CONTAINERS = [
  'block',
  'break',
  'cursor',
  'inline',
  'scroll',
  'text',
  'list-container',
];

interface DebugLogger {
  error(message: string): void;
}

/**
 * Create a new Parchment Registry containing only the specified formats
 * plus Quill's core blots and their required containers.
 *
 * @param formats - Array of format names to include, or null/undefined to
 *   use the global registry as-is.
 * @param sourceRegistry - The registry to query for format definitions.
 * @param debug - Debug logger that reports problems via error().
 * @returns A new Parchment Registry, or null to signal that the caller
 *   should fall back to the global registry.
 */
function createRegistryWithFormats(
  formats: string[] | null | undefined,
  sourceRegistry: Parchment.Registry,
  debug: DebugLogger,
): Parchment.Registry | null {
  // When formats is null or not given, the caller should use the global
  // registry; signal that by returning null.
  if (formats == null) {
    return null;
  }

  const registry = new Parchment.Registry();

  // First, register core blots that are always required
  const registered = new Set<string>();
  const toRegister: string[] = [...CORE_BLOT_NAMES];

  // Expand: for each format name, also collect its requiredContainer
  // (recursively).  Unknown names are silently skipped.
  const queue = [...formats];
  const seen = new Set<string>();

  while (queue.length > 0) {
    const name = queue.shift()!;
    if (seen.has(name)) continue;
    seen.add(name);

    const def = sourceRegistry.query(name);
    if (def == null) {
      // Unknown format – silently skip
      continue;
    }

    // @ts-expect-error def may be a BlotConstructor with requiredContainer
    const requiredContainer = (def as { requiredContainer?: unknown }).requiredContainer;
    if (requiredContainer != null) {
      // @ts-expect-error
      const containerName = (requiredContainer as { blotName: string }).blotName;
      if (containerName != null && !seen.has(containerName)) {
        queue.push(containerName);
      }
    }

    // After the queue has consumed the requiredContainer, register the
    // actual format def.
  }

  // Actually register everything: core blots first, then the user-specified
  // formats in order they were discovered.
  for (const name of CORE_BLOT_NAMES) {
    const def = sourceRegistry.query(name);
    if (def != null) {
      // @ts-expect-error
      registry.register(def);
      registered.add(name);
    }
  }

  // Register user-specified formats plus any discovered requiredContainers
  for (const name of seen) {
    if (!registered.has(name)) {
      const def = sourceRegistry.query(name);
      if (def != null) {
        // @ts-expect-error
        registry.register(def);
        registered.add(name);
      }
    }
  }

  return registry;
}

export default createRegistryWithFormats;
